import React, { useEffect, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import './NewLanding.css';
import { NewLandingHero } from './NewLandingHero';
import { NewLandingMid, MaskGroupBanner } from './NewLandingMid';
import { NewLandingFooter } from './NewLandingFooter';

export { MaskGroupBanner };

export const NewLanding = () => {
  const [isReady, setIsReady] = useState(false);
  const [showLoader, setShowLoader] = useState(true);
  
  const [imagesLoaded, setImagesLoaded] = useState(false);
  const [minTimeElapsed, setMinTimeElapsed] = useState(false);

  // Enforce a minimum 1.5s loader time for a smooth entrance
  useEffect(() => {
    const timer = setTimeout(() => setMinTimeElapsed(true), 1500);
    return () => clearTimeout(timer);
  }, []);

  // Safety fallback: if images take too long to load (e.g. network issue), force ready after 4.5s
  useEffect(() => {
    const timer = setTimeout(() => setImagesLoaded(true), 4500);
    return () => clearTimeout(timer);
  }, []);

  // When both the images are loaded AND the minimum time has elapsed, we are ready
  useEffect(() => {
    let isMounted = true;
    if (imagesLoaded && minTimeElapsed) {
      setIsReady(true);
      setTimeout(() => {
        if (isMounted) setShowLoader(false);
      }, 500);
    }
    return () => { isMounted = false; };
  }, [imagesLoaded, minTimeElapsed]);

  const handleImageLoad = () => {
    setLoadedImagesCount(prev => {
      const nextCount = prev + 1;
      if (nextCount >= 3) {
        setImagesLoaded(true);
      }
      return nextCount;
    });
  };

  const [, setLoadedImagesCount] = useState(0);

  /* Scroll-in animation */
  useEffect(() => {
    if (!isReady) return;
    const targets = document.querySelectorAll('.nl-animate');
    const observer = new IntersectionObserver(
      entries => entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); }),
      { threshold: 0.08 }
    );
    targets.forEach(t => observer.observe(t));
    return () => observer.disconnect();
  }, [isReady]);

  return (
    <div className="nl-root">
      <AnimatePresence>
        {showLoader && !isReady && (
          <motion.div
            className="nl-loader-overlay"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
          >
            <div className="nl-loader-spinner" />
            <div className="nl-loader-logo">DISHASTRA</div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Hidden preloader container to force the browser to resolve and download the optimal responsive formats (AVIF/WebP) */}
      {!isReady && (
        <div style={{ position: 'absolute', top: '-9999px', left: '-9999px', width: '10px', height: '10px', opacity: 0.01, pointerEvents: 'none', zIndex: -1 }}>
          <picture>
            <source srcSet={`${process.env.PUBLIC_URL}/bg hero.avif`} type="image/avif" />
            <source srcSet={`${process.env.PUBLIC_URL}/bg hero.webp`} type="image/webp" />
            <img src={`${process.env.PUBLIC_URL}/bg hero.png`} alt="" onLoad={handleImageLoad} onError={handleImageLoad} />
          </picture>
          <picture>
            <source srcSet={`${process.env.PUBLIC_URL}/hero bg new.avif`} type="image/avif" />
            <source srcSet={`${process.env.PUBLIC_URL}/hero bg new.webp`} type="image/webp" />
            <img src={`${process.env.PUBLIC_URL}/hero bg new.png`} alt="" onLoad={handleImageLoad} onError={handleImageLoad} />
          </picture>
          <picture>
            <source srcSet={`${process.env.PUBLIC_URL}/image.avif`} type="image/avif" />
            <source srcSet={`${process.env.PUBLIC_URL}/image.webp`} type="image/webp" />
            <img src={`${process.env.PUBLIC_URL}/image.png`} alt="" onLoad={handleImageLoad} onError={handleImageLoad} />
          </picture>
        </div>
      )}

      {/* Render content only after critical assets are ready so entrance animations start cleanly from 0s right as the loader dissolves */}
      {isReady && (
        <>
          <NewLandingHero />
          <NewLandingMid />
          <NewLandingFooter />
        </>
      )}
    </div>
  );
};
