import React, { useRef } from 'react';

import { motion, useReducedMotion, useScroll, useTransform } from 'framer-motion';
import './NewLanding.css';

const CONTAINER_VARIANTS = Object.freeze({
  hidden: {},
  show: {
    transition: { staggerChildren: 0.15, delayChildren: 0.1 }
  }
});

const BLUR_REVEAL_VARIANTS = Object.freeze({
  hidden: { opacity: 0, y: 40, filter: 'blur(20px)', scale: 1.05 },
  show: { opacity: 1, y: 0, filter: 'blur(0px)', scale: 1, transition: { duration: 1.4, ease: [0.22, 1, 0.36, 1] } }
});

const DASHBOARD_TRANSITION = Object.freeze({ duration: 1.6, delay: 0.15, ease: [0.22, 1, 0.36, 1] });
const HILLS_TRANSITION = Object.freeze({ duration: 1.8, ease: [0.22, 1, 0.36, 1] });

export const NewLandingHero = React.memo(() => {

  const heroRef = useRef(null);
  const prefersReducedMotion = useReducedMotion();
  const [isMobileOrTablet, setIsMobileOrTablet] = React.useState(
    typeof window !== 'undefined' ? window.matchMedia('(max-width: 1024px)').matches : false
  );

  React.useEffect(() => {
    const mediaQuery = window.matchMedia('(max-width: 1024px)');
    const handleMediaChange = (e) => setIsMobileOrTablet(e.matches);
    setIsMobileOrTablet(mediaQuery.matches);
    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener('change', handleMediaChange);
      return () => mediaQuery.removeEventListener('change', handleMediaChange);
    } else {
      mediaQuery.addListener(handleMediaChange);
      return () => mediaQuery.removeListener(handleMediaChange);
    }
  }, []);

  const disableParallax = prefersReducedMotion || isMobileOrTablet;
  const { scrollYProgress } = useScroll({
    target: heroRef,
    offset: ['start start', 'end start'],
  });

  const bgY = useTransform(scrollYProgress, [0, 1], [0, disableParallax ? 0 : -60]);
  const contentY = useTransform(scrollYProgress, [0, 1], [0, disableParallax ? 0 : -20]);
  const dashboardY = useTransform(scrollYProgress, [0, 1], [0, prefersReducedMotion ? 0 : (isMobileOrTablet ? 110 : 140)]);
  const hillsY = useTransform(scrollYProgress, [0, 0.6, 1], [0, disableParallax ? 0 : -150, disableParallax ? 0 : -150]);

  return (
    <motion.section className="nl-hero" ref={heroRef}>

      {/* Sky background */}
      <picture className="nl-hero-bg-picture" style={{ display: 'contents' }}>
        <source srcSet={`${process.env.PUBLIC_URL}/bg%20hero.avif`} type="image/avif" />
        <source srcSet={`${process.env.PUBLIC_URL}/bg%20hero.webp`} type="image/webp" />
        <motion.img
          className="nl-hero-bg"
          src={`${process.env.PUBLIC_URL}/bg%20hero.png`}
          alt=""
          aria-hidden="true"
          fetchpriority="high"
          loading="eager"
          decoding="async"
          style={{ y: bgY }}
        />
      </picture>

      {/* Top-to-bottom gradient: subtle dark at top, light-to-dark mid, very dark at bottom */}
      <div className="nl-hero-overlay" aria-hidden="true"/>

      {/* ── Text Content ── */}
      <motion.div
        className="nl-hero-content"
        style={{ y: contentY }}
        initial="hidden"
        animate="show"
        variants={CONTAINER_VARIANTS}
      >
        <motion.h1 
          className="nl-hero-heading"
          variants={BLUR_REVEAL_VARIANTS}
        >
          The intelligent travel companion<br/>
          for <em>every journey you take.</em>
        </motion.h1>

        <motion.p 
          className="nl-hero-subtitle"
          variants={BLUR_REVEAL_VARIANTS}
        >
          Your journey, our priority. Powered by AI, tailored for you.
        </motion.p>

        <motion.div 
          className="nl-cta-row"
          variants={BLUR_REVEAL_VARIANTS}
        >
          <button
            id="nl-try-beta"
            className="nl-btn-hero-white"
            onClick={() => window.location.href = 'https://dishastra.saigal.dev/'}
          >
            Join the Beta
          </button>
        </motion.div>
      </motion.div>

      {/* ── Dashboard Preview ── */}
      <motion.div
        className="nl-dashboard-wrap"
        style={{ y: dashboardY }}
      >
        <motion.div 
          className="nl-dashboard-card"
          initial={{ y: 350 }}
          animate={{ y: 0 }}
          transition={DASHBOARD_TRANSITION}
        >
          <picture className="nl-dashboard-picture" style={{ display: 'contents' }}>
            <source srcSet={`${process.env.PUBLIC_URL}/hero%20bg%20new.avif`} type="image/avif" />
            <source srcSet={`${process.env.PUBLIC_URL}/hero%20bg%20new.webp`} type="image/webp" />
            <img
              src={`${process.env.PUBLIC_URL}/hero%20bg%20new.png`}
              alt="Dishastra Dashboard"
              className="nl-dashboard-img"
              fetchpriority="high"
              loading="eager"
              decoding="async"
            />
          </picture>
        </motion.div>
      </motion.div>

      {/* ── Hills — IN FRONT of dashboard, bottom of hero ── */}
      <div className="nl-hills-wrap" aria-hidden="true">
        <motion.div style={{ y: hillsY, width: '100%', height: '100%' }}>
          <picture className="nl-hills-picture" style={{ display: 'contents' }}>
            <source srcSet={`${process.env.PUBLIC_URL}/image.avif`} type="image/avif" />
            <source srcSet={`${process.env.PUBLIC_URL}/image.webp`} type="image/webp" />
            <motion.img
              src={`${process.env.PUBLIC_URL}/image.png`}
              alt=""
              className="nl-hills-img"
              fetchpriority="high"
              loading="eager"
              decoding="async"
              initial={{ y: 80 }}
              animate={{ y: 0 }}
              transition={HILLS_TRANSITION}
            />
          </picture>
        </motion.div>
      </div>

    </motion.section>
  );
});
